Desarrollador: Agustin Omar Cauzi | Correo: agustincauzi10@hotmail.com | Descripción funcional: Impide estados, cantidades y documentos industriales incompatibles. | Historial: 1.0.0 | 2026-08-24 | FABRICA | Agustin Omar Cauzi | Creación inicial. */
ALTER TABLE [INVENTARIO].[PRODUCTOS] ADD CONSTRAINT [CK_PRODUCTOS_TIPO_TRAZABILIDAD] CHECK ([TIPO_TRAZABILIDAD] IN (N'NINGUNA', N'LOTE', N'SERIE', N'SERIE_LOTE'));
ALTER TABLE [COMPRAS].[ORDENES_COMPRA] ADD CONSTRAINT [CK_ORDENES_COMPRA_IMPORTES] CHECK ([SUBTOTAL] >= 0 AND [TOTAL_DESCUENTO] >= 0 AND [TOTAL_IMPUESTO] >= 0 AND [TOTAL] >= 0);
ALTER TABLE [COMPRAS].[ORDENES_COMPRA_DETALLES] ADD CONSTRAINT [CK_ORDENES_COMPRA_DETALLES_CANTIDADES] CHECK ([CANTIDAD_PEDIDA] > 0 AND [CANTIDAD_RECIBIDA] >= 0 AND [CANTIDAD_CERRADA] >= 0 AND [CANTIDAD_RECIBIDA] + [CANTIDAD_CERRADA] <= [CANTIDAD_PEDIDA]);
ALTER TABLE [COMPRAS].[RECEPCIONES_COMPRA_DETALLES] ADD CONSTRAINT [CK_RECEPCIONES_DETALLES_CANTIDADES] CHECK ([CANTIDAD_ACEPTADA] >= 0 AND [CANTIDAD_RECHAZADA] >= 0 AND [CANTIDAD_DANADA] >= 0 AND [CANTIDAD_ACEPTADA] + [CANTIDAD_RECHAZADA] + [CANTIDAD_DANADA] > 0);
ALTER TABLE [INVENTARIO].[LOTES] ADD CONSTRAINT [CK_LOTES_CANTIDAD_FECHAS] CHECK ([CANTIDAD_INICIAL] > 0 AND ([FECHA_VENCIMIENTO] IS NULL OR [FECHA_FABRICACION] IS NULL OR [FECHA_VENCIMIENTO] >= [FECHA_FABRICACION]));
ALTER TABLE [INVENTARIO].[LOTES_EXISTENCIAS] ADD CONSTRAINT [CK_LOTES_EXISTENCIAS_CANTIDAD] CHECK ([CANTIDAD] >= 0);
ALTER TABLE [INVENTARIO].[ACTIVOS] ADD CONSTRAINT [CK_ACTIVOS_CAPACIDAD] CHECK ([CAPACIDAD] IS NULL OR [CAPACIDAD] > 0);
ALTER TABLE [INVENTARIO].[ACTIVOS_CONTENIDOS] ADD CONSTRAINT [CK_ACTIVOS_CONTENIDOS_CANTIDAD] CHECK ([CANTIDAD_ACTUAL] >= 0);
ALTER TABLE [INVENTARIO].[MEDICIONES_ACTIVOS] ADD CONSTRAINT [CK_MEDICIONES_ORIGEN] CHECK ([ORIGEN_MEDICION] IN (N'MANUAL', N'PESAJE', N'CALCULADO', N'SENSOR'));
ALTER TABLE [INVENTARIO].[TRANSFORMACIONES] ADD CONSTRAINT [CK_TRANSFORMACIONES_CANTIDADES] CHECK ([CANTIDAD_ORIGEN] > 0 AND [CANTIDAD_MERMA] >= 0 AND [CANTIDAD_MERMA] <= [CANTIDAD_ORIGEN]);
ALTER TABLE [INVENTARIO].[TRANSFORMACIONES_DETALLES] ADD CONSTRAINT [CK_TRANSFORMACIONES_DETALLES_CANTIDADES] CHECK ([CANTIDAD_ANTES] >= 0 AND [CANTIDAD_CARGADA] > 0 AND [CANTIDAD_DESPUES] = [CANTIDAD_ANTES] + [CANTIDAD_CARGADA]);
ALTER TABLE [INVENTARIO].[INCIDENTES] ADD CONSTRAINT [CK_INCIDENTES_CANTIDAD] CHECK ([CANTIDAD_PERDIDA] >= 0 AND ([CANTIDAD_ANTES] IS NULL OR [CANTIDAD_DESPUES] IS NULL OR [CANTIDAD_ANTES] = [CANTIDAD_DESPUES] + [CANTIDAD_PERDIDA]));
ALTER TABLE [INVENTARIO].[MANTENIMIENTOS] ADD CONSTRAINT [CK_MANTENIMIENTOS_FECHAS_COSTO] CHECK (([FECHA_FIN_UTC] IS NULL OR [FECHA_FIN_UTC] >= [FECHA_INICIO_UTC]) AND ([COSTO] IS NULL OR [COSTO] >= 0));
ALTER TABLE [INVENTARIO].[PRESTAMOS] ADD CONSTRAINT [CK_PRESTAMOS_FECHAS] CHECK (([FECHA_DEVOLUCION_PREVISTA] IS NULL OR [FECHA_DEVOLUCION_PREVISTA] >= [FECHA_SALIDA_UTC]) AND ([FECHA_DEVOLUCION_REAL_UTC] IS NULL OR [FECHA_DEVOLUCION_REAL_UTC] >= [FECHA_SALIDA_UTC]));
ALTER TABLE [INVENTARIO].[PRESTAMOS] ADD CONSTRAINT [CK_PRESTAMOS_MODALIDAD] CHECK ([MODALIDAD_ENTREGA] IN (N'ENTREGA_PROPIA', N'RETIRO_DESTINATARIO', N'TERCERO'));
ALTER TABLE [INVENTARIO].[PRESTAMOS] ADD CONSTRAINT [CK_PRESTAMOS_DESTINO] CHECK (([TIPO_DESTINO] = N'SUCURSAL' AND [ID_SUCURSAL_DESTINO] IS NOT NULL AND [ID_CLIENTE_DESTINO] IS NULL AND [DESTINO_EXTERNO] IS NULL) OR ([TIPO_DESTINO] = N'CLIENTE' AND [ID_CLIENTE_DESTINO] IS NOT NULL AND [ID_SUCURSAL_DESTINO] IS NULL AND [DESTINO_EXTERNO] IS NULL) OR ([TIPO_DESTINO] IN (N'TERCERO', N'INTEREMPRESA') AND [DESTINO_EXTERNO] IS NOT NULL AND [ID_SUCURSAL_DESTINO] IS NULL AND [ID_CLIENTE_DESTINO] IS NULL));
ALTER TABLE [INVENTARIO].[PRESTAMOS_DETALLES] ADD CONSTRAINT [CK_PRESTAMOS_DETALLES_CANTIDAD] CHECK (([CANTIDAD_SALIDA] IS NULL OR [CANTIDAD_SALIDA] >= 0) AND ([CANTIDAD_DEVUELTA] IS NULL OR [CANTIDAD_DEVUELTA] >= 0));
ALTER TABLE [INVENTARIO].[ACTIVOS_EVENTOS] ADD CONSTRAINT [CK_ACTIVOS_EVENTOS_ORIGEN] CHECK (CONVERT(INT, CASE WHEN [ID_RECEPCION_COMPRA] IS NULL THEN 0 ELSE 1 END) + CONVERT(INT, CASE WHEN [ID_MEDICION_ACTIVO] IS NULL THEN 0 ELSE 1 END) + CONVERT(INT, CASE WHEN [ID_TRANSFORMACION] IS NULL THEN 0 ELSE 1 END) + CONVERT(INT, CASE WHEN [ID_INCIDENTE] IS NULL THEN 0 ELSE 1 END) + CONVERT(INT, CASE WHEN [ID_MANTENIMIENTO] IS NULL THEN 0 ELSE 1 END) + CONVERT(INT, CASE WHEN [ID_PRESTAMO] IS NULL THEN 0 ELSE 1 END) = CASE WHEN [TIPO_EVENTO] IN (N'CLIENTE_ALTA', N'CLIENTE_INGRESO', N'CLIENTE_ENTREGA') THEN 0 ELSE 1 END);
